type To_2&lt;Type extends Callable|Constructor, Args extends any[], Ret extends (Constructor extends Type ? object : any) = (Constructor extends Type ? object : void)&gt; = NotAnyNever&lt;Type&gt; extends true
    ? IsUnion_3&lt;Type&gt; extends false
        ? {
            0: (...arg: [...Args]) =&gt; Ret;
            1: {
                new (...arg: [...Args]): Ret;
                readonly prototype: Ret;
            };
        }[Type]
        : never
    : never;

class MyClass {}

type TT = To_2&lt;any, []&gt;; &#47;&#47; 得到 never
type TT_2 = To_2&lt;never, []&gt;; &#47;&#47; 得到 never
type TT_3 = To_2&lt;Callable|Constructor, []&gt;; &#47;&#47; 得到 never
&#47;&#47; TT_4 = {
&#47;&#47;                 new (arg_0: string, arg_1: number, arg_2: &quot;a&quot; | &quot;b&quot;): MyClass;
&#47;&#47;                 readonly prototype: MyClass;
&#47;&#47; }
type TT_4 = To_2&lt;Constructor, [string, number, &#39;a&#39;|&#39;b&#39;], MyClass&gt;;
type TT_5 = To_2&lt;Constructor, [string, number, &#39;a&#39;|&#39;b&#39;], void&gt;; &#47;&#47; 编译错误，Type &#39;void&#39; does not satisfy the constraint &#39;object&#39;

type IsAny&lt;T&gt; = 0 extends 1 &amp; T ? true : false;
type IsNever&lt;T&gt; = [T] extends [never] ? true : false;
type IsVoidOrUndefined&lt;T&gt; = [T] extends [void]
  ? NotAnyNever&lt;T&gt;
  : false;
type IsUnion&lt;T&gt; = T[] extends (infer U)[] ? [U] extends [infer t] ? ([T] extends [t] ? false : true) : never : never;
type IsInterface&lt;T&gt; = [T] extends [object]
  ? NotAnyNever&lt;T&gt;
  : false; 

type Not&lt;T extends boolean&gt; = true extends T ? false : true;
type NotAnyNever&lt;T&gt; = false extends IsAny&lt;T&gt; ? Not&lt;IsNever&lt;T&gt;&gt; : false;
type NotVoidUndefined&lt;T&gt; = false extends IsVoidOrUndefined&lt;T&gt; ? true : false;

type Callable = 0;
type Constructor = 1;

type Gen&lt;Type extends Callable|Constructor, Args extends any[], Ret = void&gt; = IsUnion&lt;Type&gt; extends (false | never) ? 
  IsInterface&lt;Ret&gt; extends true ? Table&lt;Type, Args, Ret&gt; : 
    Type extends Constructor ? never : Table&lt;Type, Args, Ret&gt;
    : Gen&lt;Type, Args, Ret&gt;;


type Table&lt;Type extends Callable|Constructor, Args extends any[], Ret = void&gt; = {
    0: (...arg: [...Args]) =&gt; Ret;
    1: {
        new (...arg: [...Args]): Ret;
        readonly prototype: Ret;
    };
}[Type]

type To&lt;Type extends Callable|Constructor, Args extends any[], Ret = void&gt; = NotAnyNever&lt;Type&gt; extends true ? Gen&lt;Type, Args, Ret&gt; : unknown;

